/**
 * A small deterministic PRNG, so every dataset in `data/` can be regenerated byte-for-byte from its
 * seed. `Math.random()` is deliberately not used anywhere in this harness: a benchmark whose inputs
 * cannot be reproduced is not evidence.
 *
 * mulberry32 — 32-bit state, passes gjrand and PractRand well past the sample sizes here, and is
 * four lines. Quality beyond that would be false precision: nothing in the dataset depends on the
 * spectral properties of the stream.
 */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Everything the dataset builder needs, bound to one stream. */
export class Rng {
  constructor(seed) {
    this.seed = seed >>> 0;
    this.next = mulberry32(seed);
  }

  /** Uniform float in [0, 1). */
  float() { return this.next(); }

  /** Uniform integer in [lo, hi], inclusive. */
  int(lo, hi) { return lo + Math.floor(this.next() * (hi - lo + 1)); }

  /** Uniform integer in [lo, hi] rounded down to a multiple of `step`. */
  step(lo, hi, step) {
    const n = this.int(lo, hi);
    return Math.max(lo, Math.round(n / step) * step);
  }

  /** True with probability p. */
  chance(p) { return this.next() < p; }

  /** One element, uniformly. */
  pick(list) { return list[Math.floor(this.next() * list.length)]; }

  /**
   * One key of `weights` ({ key: weight }), drawn proportionally. Used for every categorical
   * distribution in the dataset (course type, lecturer position, group count) so that the
   * proportions are stated once, as data, and can be read off in the README.
   */
  weighted(weights) {
    const entries = Object.entries(weights);
    const total = entries.reduce((s, [, w]) => s + w, 0);
    let r = this.next() * total;
    for (const [k, w] of entries) { r -= w; if (r <= 0) return k; }
    return entries[entries.length - 1][0];
  }

  /** Fisher–Yates, in place; returns the same array. */
  shuffle(list) {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  }

  /** `k` distinct elements of `list` (or all of it, if k >= length). */
  sample(list, k) {
    if (k >= list.length) return [...list];
    const copy = [...list];
    const out = [];
    for (let i = 0; i < k; i++) {
      const j = i + Math.floor(this.next() * (copy.length - i));
      [copy[i], copy[j]] = [copy[j], copy[i]];
      out.push(copy[i]);
    }
    return out;
  }

  /**
   * Integer from a triangular distribution on [lo, hi] peaking at `mode`. Desirability scores and
   * hour counts are not uniform in practice — most sit near a typical value with thin tails — and a
   * uniform draw would make every candidate pool look interchangeable.
   */
  triangular(lo, hi, mode) {
    const u = this.next();
    const c = (mode - lo) / (hi - lo);
    const x = u < c
      ? lo + Math.sqrt(u * (hi - lo) * (mode - lo))
      : hi - Math.sqrt((1 - u) * (hi - lo) * (hi - mode));
    return Math.round(x);
  }
}
